package org.eclipse.rdf4j.sail.lmdb.bulk;

import static java.nio.charset.StandardCharsets.UTF_8;
import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.io.ByteArrayInputStream;
import java.io.IOException;

import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.eclipse.rdf4j.rio.RDFParseException;
import org.junit.jupiter.api.Test;

class FastNTriplesParserTest {

	@Test
	void rejectsEightDigitUnicodeEscapesOutsideTheCodePointRange() {
		assertInvalid("<http://example.org/\\UFFFFFF41> <urn:p> <urn:o> .\n");
		assertInvalid("<http://example.org/\\UFFFFFF20> <urn:p> <urn:o> .\n");
		assertInvalid("<urn:s> <urn:p> \"a\\UFFFFFF22b\" .\n");
		assertInvalid("<urn:s> <urn:p> \"a\\UFFFFFF00b\" .\n");
	}

	@Test
	void acceptsTheHighestUnicodeCodePoint() throws IOException {
		FastNTriplesParser parser = new FastNTriplesParser(RDFFormat.NTRIPLES, () -> false);

		long statements = parser.parse(
				new ByteArrayInputStream("<http://example.org/\\U0010FFFF> <urn:p> <urn:o> .\n".getBytes(UTF_8)),
				(subject, predicate, object, context) -> {
				});

		assertEquals(1L, statements);
	}

	@Test
	void acceptsSupplementaryIriCodePointWhoseLowBitsLookLikeASurrogate() throws IOException {
		byte[][] terms = parse("<http://example.org/\\U0001D800> <urn:p> <urn:o> .\n");
		ValueFactory vf = SimpleValueFactory.getInstance();

		assertArrayEquals(
				CanonicalTermCodec.encode(vf.createIRI("http://example.org/" + new String(Character.toChars(0x1D800)))),
				terms[0]);
	}

	@Test
	void preservesSupplementaryLiteralCodePointWhoseLowBitsLookLikeASurrogate() throws IOException {
		byte[][] terms = parse("<urn:s> <urn:p> \"a\\U0001D800b\" .\n");
		ValueFactory vf = SimpleValueFactory.getInstance();

		assertArrayEquals(
				CanonicalTermCodec.encode(vf.createLiteral("a" + new String(Character.toChars(0x1D800)) + "b")),
				terms[2]);
	}

	private static byte[][] parse(String input) throws IOException {
		FastNTriplesParser parser = new FastNTriplesParser(RDFFormat.NTRIPLES, () -> false);
		byte[][] terms = new byte[3][];
		parser.parse(new ByteArrayInputStream(input.getBytes(UTF_8)), (subject, predicate, object, context) -> {
			terms[0] = subject;
			terms[1] = predicate;
			terms[2] = object;
		});
		return terms;
	}

	private static void assertInvalid(String input) {
		FastNTriplesParser parser = new FastNTriplesParser(RDFFormat.NTRIPLES, () -> false);
		assertThrows(RDFParseException.class,
				() -> parser.parse(new ByteArrayInputStream(input.getBytes(UTF_8)),
						(subject, predicate, object, context) -> {
						}));
	}
}
